import re

def parse(lines):
    rows = []
    idx = []
    skip = []
    order = []
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if re.search(r'[>$#]\s*lssyscfg\b', s) or re.match(r'^lssyscfg\b', s):
            skip.append(i)
            continue
        if not re.match(r'^"?[A-Za-z_]\w*=', s):
            continue
        rec = {}
        for tok in re.findall(r'(?:"[^"]*"|[^,"])+', s):
            tok = tok.strip()
            if len(tok) >= 2 and tok.startswith('"') and tok.endswith('"'):
                tok = tok[1:-1]
            if '=' not in tok:
                continue
            k, v = tok.split('=', 1)
            k = k.strip().strip('"')
            v = v.strip().strip('"')
            if not k:
                continue
            rec[k] = v
            if k not in order:
                order.append(k)
        if rec:
            rows.append(rec)
            idx.append(i)
    blocks = []
    if rows:
        recs = []
        for r in rows:
            recs.append({k: r.get(k, '') for k in order})
        blocks.append({'name': 'lpars', 'kind': 'table', 'lines': idx, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
